#include "Solver.h"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <stdexcept>

namespace { constexpr double pi=3.14159265358979323846; bool branch(Solver::Kind k,Solver::Analysis a){return k==Solver::Kind::Voltage||k==Solver::Kind::Vcvs||k==Solver::Kind::Ccvs||(k==Solver::Kind::Inductor&&a!=Solver::Analysis::Ac);} }
void Solver::addElement(Element e){if(e.name.empty()||e.p<0||e.n<0||e.cp<0||e.cn<0)throw std::invalid_argument("Element names and nodes must be valid");if((e.kind==Kind::Resistor||e.kind==Kind::Capacitor||e.kind==Kind::Inductor)&&e.value<=0)throw std::invalid_argument(e.name+" requires a positive value");nodeCount_=std::max({nodeCount_,e.p,e.n,e.cp,e.cn});elements_.push_back(std::move(e));solved_=false;}
void Solver::setTransient(double dt,double stop){if(dt<=0||stop<=0)throw std::invalid_argument(".tran values must be positive");transientStep_=dt;transientStop_=stop;}
void Solver::setAcSweep(int n,double start,double stop){if(n<1||start<=0||stop<start)throw std::invalid_argument("Invalid .ac sweep");acPoints_=n;acStartHz_=start;acStopHz_=stop;}
Solver::BranchLayout Solver::makeBranchLayout(Analysis a)const{BranchLayout l;for(const auto&e:elements_)if(branch(e.kind,a))l.index.emplace(e.name,l.count++);return l;}
void Solver::stampConductance(Eigen::MatrixXcd&a,int p,int n,Complex g)const{if(p>=0)a(p,p)+=g;if(n>=0)a(n,n)+=g;if(p>=0&&n>=0){a(p,n)-=g;a(n,p)-=g;}}
void Solver::stampCurrent(Eigen::VectorXcd&z,int p,int n,Complex i)const{if(p>=0)z(p)-=i;if(n>=0)z(n)+=i;}
void Solver::stampBranch(Eigen::MatrixXcd&a,Eigen::VectorXcd&z,const Element&e,int b,Complex rhs,int cp,int cn)const{int p=nodeIndex(e.p),n=nodeIndex(e.n);if(p>=0){a(p,b)+=1.;a(b,p)+=1.;}if(n>=0){a(n,b)-=1.;a(b,n)-=1.;}if(cp>=0)a(b,cp)-=e.value;if(cn>=0)a(b,cn)+=e.value;z(b)+=rhs;}
Eigen::VectorXcd Solver::assembleAndSolve(Analysis mode,double f,double dt){auto bl=makeBranchLayout(mode);int dim=nodeCount_+bl.count;if(!dim)throw std::runtime_error("Circuit contains no unknowns");Eigen::MatrixXcd a=Eigen::MatrixXcd::Zero(dim,dim);Eigen::VectorXcd z=Eigen::VectorXcd::Zero(dim);Complex jw(0,2*pi*f);for(const auto&e:elements_){int p=nodeIndex(e.p),n=nodeIndex(e.n),cp=nodeIndex(e.cp),cn=nodeIndex(e.cn);switch(e.kind){case Kind::Resistor:stampConductance(a,p,n,1./e.value);break;case Kind::Capacitor:if(mode==Analysis::Ac)stampConductance(a,p,n,jw*e.value);else if(mode==Analysis::Transient){double g=e.value/dt;stampConductance(a,p,n,g);stampCurrent(z,p,n,-g*e.previousVoltage);}break;case Kind::Inductor:if(mode==Analysis::Ac)stampConductance(a,p,n,1./(jw*e.value));else{int b=nodeCount_+bl.index.at(e.name);stampBranch(a,z,e,b,mode==Analysis::Transient?-e.value/dt*e.previousCurrent:0.,-1,-1);if(mode==Analysis::Transient)a(b,b)-=e.value/dt;}break;case Kind::Current:stampCurrent(z,p,n,mode==Analysis::Ac?std::polar(e.acMagnitude,e.acPhaseDegrees*pi/180.):Complex(e.value));break;case Kind::Voltage:{int b=nodeCount_+bl.index.at(e.name);stampBranch(a,z,e,b,mode==Analysis::Ac?std::polar(e.acMagnitude,e.acPhaseDegrees*pi/180.):Complex(e.value),-1,-1);break;}case Kind::Vccs:if(p>=0&&cp>=0)a(p,cp)+=e.value;if(p>=0&&cn>=0)a(p,cn)-=e.value;if(n>=0&&cp>=0)a(n,cp)-=e.value;if(n>=0&&cn>=0)a(n,cn)+=e.value;break;case Kind::Vcvs:{int b=nodeCount_+bl.index.at(e.name);stampBranch(a,z,e,b,0.,cp,cn);break;}case Kind::Cccs:{int c=nodeCount_+bl.index.at(e.controlName);if(p>=0)a(p,c)+=e.value;if(n>=0)a(n,c)-=e.value;break;}case Kind::Ccvs:{int b=nodeCount_+bl.index.at(e.name),c=nodeCount_+bl.index.at(e.controlName);stampBranch(a,z,e,b,0.,-1,-1);a(b,c)-=e.value;break;}}}Eigen::FullPivLU<Eigen::MatrixXcd>lu(a);if(!lu.isInvertible())throw std::runtime_error("MNA system is singular; check ground references and source topology");return lu.solve(z);}
void Solver::solve(){auto x=assembleAndSolve(Analysis::Dc,0,0);solution_=x.real();sweepResults_={{0,x}};lastAnalysis_=Analysis::Dc;solved_=true;}
void Solver::solveTransient(){if(transientStep_<=0)throw std::runtime_error("Netlist has no .tran directive");sweepResults_.clear();auto bl=makeBranchLayout(Analysis::Transient);for(double t=0;t<=transientStop_+transientStep_*1e-9;t+=transientStep_){auto x=assembleAndSolve(Analysis::Transient,0,transientStep_);sweepResults_.push_back({t,x});for(auto&e:elements_){int p=nodeIndex(e.p),n=nodeIndex(e.n);if(e.kind==Kind::Capacitor)e.previousVoltage=(x(p)-(n>=0?x(n):Complex{})).real();if(e.kind==Kind::Inductor)e.previousCurrent=x(nodeCount_+bl.index.at(e.name)).real();}}solution_=sweepResults_.back().second.real();lastAnalysis_=Analysis::Transient;solved_=true;}
void Solver::solveAc(){if(acPoints_<=0)throw std::runtime_error("Netlist has no .ac directive");sweepResults_.clear();for(int i=0;i<acPoints_;++i){double f=acPoints_==1?acStartHz_:acStartHz_*std::pow(acStopHz_/acStartHz_,double(i)/(acPoints_-1));sweepResults_.push_back({f,assembleAndSolve(Analysis::Ac,f,0)});}solution_=sweepResults_.back().second.real();lastAnalysis_=Analysis::Ac;solved_=true;}
void Solver::solveConfigured(){if(acPoints_>0)solveAc();else if(transientStep_>0)solveTransient();else solve();}
const Eigen::VectorXd& Solver::solution()const{if(!solved_)throw std::logic_error("Call solve first");return solution_;}
void Solver::printResults(std::ostream&out)const{if(!solved_)throw std::logic_error("Call solve first");out<<std::setprecision(10);if(lastAnalysis_==Analysis::Dc){out<<"Node voltages (V):\n  V(0) = 0\n";for(int n=1;n<=nodeCount_;++n)out<<"  V("<<n<<") = "<<solution_(n-1)<<'\n';return;}out<<(lastAnalysis_==Analysis::Ac?"Frequency (Hz), node voltages (real, imag)\n":"Time (s), node voltages (V)\n");for(const auto&[point,x]:sweepResults_){out<<point;for(int n=0;n<nodeCount_;++n){out<<", "<<x(n).real();if(lastAnalysis_==Analysis::Ac)out<<", "<<x(n).imag();}out<<'\n';}}
void Solver::exportResults(const std::string&path)const{std::ofstream out(path);if(!out)throw std::runtime_error("Unable to open output file: "+path);printResults(out);}
